schema:
{
  "description": "US vendor invoices",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "InvoiceDate": {
        "type": "date",
        "method": "extract",
        "description": "The date labeled \"Invoice Date\", top right, in US format MM/DD/YYYY."
      },
      "PaymentTermsDays": {
        "type": "number",
        "method": "extract",
        "description": "The number of days in the payment terms, for example 30 in \"Net 30\"."
      },
      "AmountDue": {
        "type": "number",
        "method": "extract",
        "description": "The final amount labeled \"Amount due\" or \"Total\", after tax."
      },
      "Currency": {
        "type": "string",
        "method": "classify",
        "enum": [
          "USD",
          "CAD",
          "EUR",
          "Other"
        ],
        "description": "Currency of the amounts."
      },
      "Subtotal": {
        "type": "number",
        "method": "extract",
        "description": "Amount before tax, labeled \"Subtotal\"."
      }
    }
  }
}
